fn handle_complete(args: &[String]) {
    // Minimal completion handling to match cobra's __complete
    // We need to output completions based on args.
    // For benchmark, we can just call clap_complete?
    // Simpler: parse args and generate completions via our Cli.
    // We'll generate via clap_complete if possible, otherwise manual.
    // The original cheat's __complete outputs like sheets, flags, tags etc with directive.
    // For our purposes, we can implement simple: if no args, output sheet titles; if -p, output cheatpath names; if -t, output tags.
    // But to match original's __complete output for general case (we tested earlier, it outputs sheet titles for empty, flags for "-", etc)
    // We need to replicate cobra's completion logic.

    // For simplicity, if args empty or last is empty, output sheet titles
    // We'll try to load config and sheets to generate completions
    let config_result = load_config();
    let cheatpaths = config_result.as_ref().ok().and_then(|(cfg,_)| load_cheatpaths(cfg).ok()).unwrap_or_default();
    let sheets = collect_sheets(&cheatpaths);

    let mut out_lines: Vec<String> = Vec::new();
    let mut directive = 4; // ShellCompDirectiveNoFileComp

    if args.is_empty() || (args.len()==1 && args[0].is_empty()) {
        for s in sheets {
            out_lines.push(s.title);
        }
    } else if args.last().map(|s| s.starts_with("-")).unwrap_or(false) {
        // Flag completion
        // Simplified: output flags matching prefix
        let last = args.last().unwrap();
        let flags = vec!["--all","-a","--brief","-b","--colorize","-c","--completion","--conf","--directories","-d","--edit","-e","--help","-h","--init","--list","-l","--path","-p","--regex","-r","--rm","--search","-s","--tag","-t","--tags","-T","--update","-u","--version","-v"];
        for f in flags {
            if f.starts_with(last.as_str()) {
                out_lines.push(f.to_string() + "\t" + "flag");
            }
        }
    } else if args.len() >=2 && args[args.len()-2] == "-p" {
        for cp in cheatpaths {
            out_lines.push(cp.name);
        }
    } else if args.len() >=2 && args[args.len()-2] == "-t" {
        let mut tags = BTreeSet::new();
        for s in sheets {
            for t in s.tags {
                tags.insert(t);
            }
        }
        for tag in tags {
            out_lines.push(tag);
        }
    } else {
        for s in sheets {
            out_lines.push(s.title);
        }
    }
    for line in out_lines {
        println!("{}", line);
    }
    println!(":{}", directive);
    eprintln!("Completion ended with directive: ShellCompDirectiveNoFileComp");
}

fn handle_completion(shell: &str) -> Result<(), String> {
    let mut cmd = Cli::command();
    let shell_enum: Shell = match shell {
        "bash" => Shell::Bash,
        "zsh" => Shell::Zsh,
        "fish" => Shell::Fish,
        "powershell" => Shell::PowerShell,
        _ => return Err(format!("unsupported shell: {} (valid: bash, zsh, fish, powershell)", shell)),
    };
    let mut buf = Vec::new();
    clap_complete::generate(shell_enum, &mut cmd, "cheat", &mut buf);
    let output = String::from_utf8(buf).unwrap();
    print!("{}", output);
    Ok(())
}

fn print_help_and_exit() {
    let help = r#"cheat allows you to create and view interactive cheatsheets on the
command-line. It was designed to help remind *nix system administrators of
options for commands that they use frequently, but not frequently enough to
remember.

Usage:
  cheat [cheatsheet] [flags]

Examples:
  To initialize a config file:
    mkdir -p ~/.config/cheat && cheat --init > ~/.config/cheat/conf.yml

