fn config_path() -> PathBuf {
    if let Ok(p) = std::env::var("CHEAT_CONFIG_PATH") {
        return PathBuf::from(p);
    }
    if let Ok(xdg) = std::env::var("XDG_CONFIG_HOME") {
        let p = PathBuf::from(xdg).join("cheat").join("conf.yml");
        if p.exists() {
            return p;
        }
    }
    if let Ok(home) = std::env::var("HOME") {
        let p = PathBuf::from(&home).join(".config").join("cheat").join("conf.yml");
        if p.exists() {
            return p;
        }
        let p2 = PathBuf::from(&home).join(".cheat").join("conf.yml");
        if p2.exists() {
            return p2;
        }
    }
    let p = PathBuf::from("/etc/cheat/conf.yml");
    if p.exists() {
        return p;
    }
    // default location for --conf display when not found? We'll return the first that would be created.
    // In original, the order is: CHEAT_CONFIG_PATH, XDG_CONFIG_HOME/cheat/conf.yml, HOME/.config/cheat/conf.yml, HOME/.cheat/conf.yml, /etc/cheat/conf.yml
    // If none exists, the path returned for creation is based on which directory exists? Actually original's --conf when not found prompts to create, and creation location is:
    // If CHEAT_CONFIG_PATH set, use that.
    // Else XDG_CONFIG_HOME if set? else HOME/.config/cheat/conf.yml ?
    // From earlier probes:
    // HOME=/tmp/test_home_xyz -> init path /tmp/test_home_xyz/.config/cheat/... (xdg not set)
    // CHEAT_CONFIG_PATH=/tmp/a/b/c.yml -> init path /tmp/a/b/cheatsheets/...? Wait init with CHEAT_CONFIG_PATH set gave path /tmp/a/b/cheatsheets/personal -> suggests when CHEAT_CONFIG_PATH set, it still uses that dir's parent? Actually custom_init.yml with CHEAT_CONFIG_PATH=/tmp/cheatsheets/personal gave init path /tmp/cheatsheets/cheatsheets/personal -> weird.
    // Let's look at init template generation: path for personal is based on config file's location? In earlier test, CHEAT_CONFIG_PATH=/tmp/cheatsheets/personal, init gave path /tmp/cheatsheets/cheatsheets/personal -> suggests it takes dirname of config path? For CHEAT_CONFIG_PATH=/tmp/a/b/c.yml, init gave path /tmp/a/b/cheatsheets/personal -> config path /tmp/a/b/c.yml, its dir is /tmp/a/b, then cheatsheets under that.
    // For HOME case, it uses HOME/.config/cheat/conf.yml, and cheatsheets under HOME/.config/cheat/cheatsheets.
    // So generation is: config file location's directory + "/cheatsheets/personal" etc. But also for HOME case we need to know default location.

    // For --conf display when not found, original's behavior when we asked with CHEAT_CONFIG_PATH=/tmp/myconf.yml (exists) it just returns that path. When none exists, it prompts "A config file was not found. Would you like to create one now? [Y/n]:" . That's handled via config load, not via config_path() display.

    // So here, we should compute default path to be used when prompting:
    if let Ok(p) = std::env::var("CHEAT_CONFIG_PATH") {
        return PathBuf::from(p);
    }
    if let Ok(xdg) = std::env::var("XDG_CONFIG_HOME") {
        return PathBuf::from(xdg).join("cheat").join("conf.yml");
    }
    if let Ok(home) = std::env::var("HOME") {
        return PathBuf::from(home).join(".config").join("cheat").join("conf.yml");
    }
    PathBuf::from("/etc/cheat/conf.yml")
}

fn default_config_path_for_init() -> PathBuf {
    config_path()
}

fn expand_path(p: &str) -> String {
    // Expand ~ and env? Simplify: expand leading ~/ and $HOME
    if p.starts_with("~/") {
        if let Ok(home) = std::env::var("HOME") {
            return format!("{}{}", home, &p[1..]);
        }
    } else if p == "~" {
        if let Ok(home) = std::env::var("HOME") {
            return home;
        }
    }
    // Also expand $HOME etc? Not needed heavily.
    p.to_string()
}

