fn load_cheatpaths(config: &Config) -> Result<Vec<LoadedCheatPath>, String> {
    let mut out = Vec::new();
    for cp in &config.cheatpaths {
        let raw_path = expand_path(&cp.path);
        // Check if path contains glob characters? If contains * or ?, we try to expand via glob.
        // Original behavior: it appears to skip if literal path doesn't exist, and warns.
        // For glob paths, we need to expand.
        let has_glob = raw_path.contains('*') || raw_path.contains('?') || raw_path.contains('[');
        if has_glob {
            // Use glob crate to expand
            // If pattern is like "~/src/.../**/.cheat", we expanded ~, then glob.
            // For **, glob crate may not support ** fully but we can handle double star via walk?
            // Simplified: use glob crate with pattern; if it returns matches, add each as separate cheatpath?
            // Original example: path: ~/src/github.com/example/**/.cheat with name example-projects
            // That suggests pattern expands to multiple directories, each becoming a cheatpath? Or the path pattern itself is stored as a cheatpath that at runtime expands to multiple directories.
            // For our implementation, expand and for each match, if directory exists, add entry.
            match glob::glob(&raw_path) {
                Ok(paths) => {
                    let mut matched = 0;
                    for entry in paths {
                        if let Ok(p) = entry {
                            if p.is_dir() {
                                out.push(LoadedCheatPath {
                                    name: cp.name.clone(),
                                    path: p,
                                    tags: cp.tags.clone().unwrap_or_default(),
                                    readonly: cp.readonly.unwrap_or(false),
                                });
                                matched += 1;
                            }
                        }
                    }
                    if matched == 0 {
                        eprintln!("WARNING: cheatpath '{}' does not exist, skipping", raw_path);
                    }
                }
                Err(e) => {
                    eprintln!("WARNING: cheatpath '{}' does not exist, skipping", raw_path);
                }
            }
        } else {
            let p = PathBuf::from(&raw_path);
            if !p.exists() {
                eprintln!("WARNING: cheatpath '{}' does not exist, skipping", raw_path);
                continue;
            }
            out.push(LoadedCheatPath {
                name: cp.name.clone(),
                path: p,
                tags: cp.tags.clone().unwrap_or_default(),
                readonly: cp.readonly.unwrap_or(false),
            });
        }
    }
    // Add cwd cheatpath if exists
    if let Ok(cwd) = std::env::current_dir() {
        let mut cur = Some(cwd.as_path());
        while let Some(dir) = cur {
            let cheat_dir = dir.join(".cheat");
            if cheat_dir.is_dir() {
                out.push(LoadedCheatPath {
                    name: "cwd".to_string(),
                    path: cheat_dir,
                    tags: vec![],
                    readonly: false,
                });
                break;
            }
            cur = dir.parent();
        }
    }
    if out.is_empty() {
        return Err("config error: no cheatpaths specified".to_string());
    }
    Ok(out)
}

fn parse_sheet_file(path: &Path, cheatpath: &LoadedCheatPath) -> Option<Sheet> {
    let content = fs::read_to_string(path).ok()?;
    // file title is relative path from cheatpath root, with forward slashes, no extension (files have no extension anyway)
    let rel = path.strip_prefix(&cheatpath.path).ok()?;
    let title = rel.to_string_lossy().replace("\\", "/");
    // Parse frontmatter
    let (tags, syntax, body) = parse_frontmatter(&content);
    let mut all_tags = cheatpath.tags.clone();
    all_tags.extend(tags.clone());
    // tags may have duplicates? Original kept duplicates: personal cheatpath plus frontmatter duplicate? In earlier -l we saw ssh tags "networking,personal,personal" duplicate personal appears twice. That indicates they don't dedup? Actually ssh file had tags [ networking, personal ] plus cheatpath tags [personal] => should be networking, personal, personal (duplicate). So we keep as is, but dedup maybe not.
    // Also ensure tags include cheatpath tags already.
    Some(Sheet {
        title,
        file: path.to_path_buf(),
        cheatpath_name: cheatpath.name.clone(),
        cheatpath_path: cheatpath.path.clone(),
        tags: all_tags,
        syntax,
        body,
        raw_content: content,
    })
}

fn parse_frontmatter(content: &str) -> (Vec<String>, Option<String>, String) {
    // Check if starts with "---\n"
    if content.starts_with("---\n") || content.starts_with("---\r\n") {
        // Find second "---" line
        let mut lines = content.lines();
        // first line is "---"
        let _first = lines.next();
        let mut front_lines = Vec::new();
        let mut found_end = false;
        let mut body_start_idx = 0;
        // Need to find offset of second --- line in original content
        // Simpler: split content by lines and find second delimiter
        let content_lines: Vec<&str> = content.lines().collect();
        // Find end delimiter index
        let mut end_idx = None;
        for (i, line) in content_lines.iter().enumerate().skip(1) {
            if line.trim() == "---" {
                end_idx = Some(i);
                break;
            }
        }
        if let Some(idx) = end_idx {
            // frontmatter is lines 1..idx-1
            let fm_content = content_lines[1..idx].join("\n");
            // Try to parse yaml frontmatter: it may have keys syntax and tags
            // tags could be [ a, b ] or single etc.
            // We'll parse via serde_yaml as generic Value
            let mut tags = Vec::new();
            let mut syntax = None;
            // Try yaml parse
            if let Ok(val) = serde_yaml::from_str::<serde_yaml::Value>(&fm_content) {
                if let Some(m) = val.as_mapping() {
                    // tags
                    if let Some(t) = m.get(&serde_yaml::Value::String("tags".to_string())) {
                        if let Some(seq) = t.as_sequence() {
                            for item in seq {
                                if let Some(s) = item.as_str() {
                                    tags.push(s.to_string());
                                } else if let Some(n) = item.as_i64() {
                                    tags.push(n.to_string());
                                }
                            }
                        } else if let Some(s) = t.as_str() {
                            tags.push(s.to_string());
                        }
                    }
                    if let Some(s) = m.get(&serde_yaml::Value::String("syntax".to_string())) {
                        if let Some(s_str) = s.as_str() {
                            syntax = Some(s_str.to_string());
                        }
                    }
                }
            }
            // Body is after idx line
            let body = content_lines[idx+1..].join("\n");
            // Preserve trailing newline? Original files may end without newline, but we need to keep as is for output. join loses trailing newline, but content may have trailing newline. We'll attempt to preserve: if original content ends with "\n", body should end with "\n"? Let's just use body as constructed; trimming may not matter for search? For view, they output body as is without frontmatter. In earlier, view output added "\n" at end if missing? Let's check: they output body plus "\n"? Our earlier view for plain sheet "plain sheet" gave "plain sheet\n" with newline.
            // The body we compute may not have trailing newline, but when viewing we pipe through pager cat which adds? We'll ensure we add "\n" if body not empty and doesn't end with "\n".
            let body_with_newline = if body.is_empty() { body } else if content.ends_with('\n') && !body.ends_with('\n') { body + "\n" } else { body };
            return (tags, syntax, body_with_newline);
        }
    }
    (Vec::new(), None, content.clone())
}

fn collect_sheets(cheatpaths: &[LoadedCheatPath]) -> Vec<Sheet> {
    let mut sheets = Vec::new();
    for cp in cheatpaths {
        // walk recursively
        for entry in walkdir::WalkDir::new(&cp.path).follow_links(false).into_iter().filter_map(|e| e.ok()) {
            if entry.file_type().is_file() {
                // Skip hidden files? Not needed. Files with no extension? Original says plain-text files with no file extension, but we include all files.
                // However, should skip .git etc? Just include all files.
                if let Some(sheet) = parse_sheet_file(entry.path(), cp) {
                    sheets.push(sheet);
                }
            }
        }
    }
    // Sort by title? Original's -l output appears sorted by title alphabetical? Let's check: earlier list order was a/b/deepNested, case1, caseTest etc alphabetical? Let's see: list order in previous probe for order_test p1/p2: list was aaa, mmm, zzz. That's alphabetical across all cheatpaths, not grouped by path. So sort by title.
    sheets.sort_by(|a,b| a.title.cmp(&b.title));
    sheets
}

fn filter_sheets_by_path_name(sheets: &[Sheet], path_filter: Option<&str>, cheatpaths: &[LoadedCheatPath]) -> Result<Vec<Sheet>, String> {
    if let Some(pname) = path_filter {
        // Validate path exists
        if !cheatpaths.iter().any(|cp| cp.name == pname) {
            return Err(format!("invalid option --path: cheatpath does not exist: {}", pname));
        }
        Ok(sheets.iter().filter(|s| s.cheatpath_name == pname).cloned().collect())
    } else {
        Ok(sheets.to_vec())
