        // So pick most local among candidates.
    }

    let target_path: PathBuf;
    let is_existing = !candidates.is_empty();

    if is_existing {
        // pick most local
        let sheet = {
            // Find most local: cheatpaths order last is most local. So pick candidate whose cheatpath appears last in cheatpaths vector.
            let mut best: Option<&Sheet> = None;
