                std::process::exit(1);
            }
        }
    }

    // Determine editor
    let editor = std::env::var("VISUAL").or(std::env::var("EDITOR")).unwrap_or_else(|_| config.editor.clone().unwrap_or_else(|| "vi".to_string()));
    // If editor is "EDITOR_PATH" placeholder, treat as not set? Original placeholder should be replaced by env? But we should handle.
    let editor = if editor == "EDITOR_PATH" {
        std::env::var("VISUAL").or(std::env::var("EDITOR")).unwrap_or_else(|_| "vi".to_string())
    } else {
        editor
    };

    // Split editor by whitespace? Original may support editor with args. We'll split.
    let mut parts = editor.split_whitespace();
    let prog = parts.next().unwrap_or("vi");
    let args: Vec<String> = parts.map(|s| s.to_string()).collect();

    let mut cmd = Command::new(prog);
    for a in args {
        cmd.arg(a);
    }
    cmd.arg(&target_path);
    cmd.stdin(Stdio::inherit());
    cmd.stdout(Stdio::inherit());
    cmd.stderr(Stdio::inherit());
    let status = cmd.status();
    match status {
        Ok(s) if s.success() => {
            // success
            // If file was newly created and is empty, maybe keep? No need to handle.
            std::process::exit(0);
        }
        Ok(s) => {
            // editor exit non-zero
            eprintln!("failed to edit cheatsheet: exit status {}", s.code().unwrap_or(1));
            std::process::exit(1);
        }
        Err(e) => {
            eprintln!("failed to edit cheatsheet: {}", e);
            std::process::exit(1);
        }
    }
}

fn find_writable_cheatpath<'a>(cheatpaths: &'a [LoadedCheatPath], path_filter: Option<&str>) -> Option<&'a LoadedCheatPath> {
    if let Some(pname) = path_filter {
        // If path_filter specified, we must return that cheatpath if it's writable, else error
        if let Some(cp) = cheatpaths.iter().find(|c| c.name == pname) {
            if !cp.readonly {
                return Some(cp);
            } else {
                // Need to find writable fallback? Original for edit with -p readonly and sheet exists readonly, it copies to writable (personal) not staying on readonly. For new sheet with -p readonly, it errors "no writeable cheatpaths found" (we saw). So if path_filter is readonly and we are creating new, we should error. For existing readonly edit, we already handled copy to writable, so this function shouldn't be called with path_filter readonly for existing? But for new, we error.
                return None;
            }
        } else {
            return None;
        }
    }
    // Find last writable (most local)
    for cp in cheatpaths.iter().rev() {
        if !cp.readonly {
            return Some(cp);
        }
    }
    None
}

