fn load_cheatpaths(config: &Config) -> Result<Vec<LoadedCheatPath>, String> {
    let mut out = Vec::new();
    for cp in &config.cheatpaths {
        let raw_path = expand_path(&cp.path);
        let has_glob = raw_path.contains('*') || raw_path.contains('?') || raw_path.contains('[');
        if has_glob {
            match glob::glob(&raw_path) {
                Ok(paths) => {
                    let mut matched = 0;
                    for entry in paths {
                        if let Ok(p) = entry {
                            if p.is_dir() {
                                out.push(LoadedCheatPath { name: cp.name.clone(), path: p, tags: cp.tags.clone().unwrap_or_default(), readonly: cp.readonly.unwrap_or(false) });
                                matched += 1;
                            }
                        }
                    }
                    if matched == 0 {
                        eprintln!("WARNING: cheatpath '{}' does not exist, skipping", raw_path);
                    }
                }
                Err(_) => {
                    eprintln!("WARNING: cheatpath '{}' does not exist, skipping", raw_path);
                }
            }
        } else {
            let p = PathBuf::from(&raw_path);
            if !p.exists() {
                eprintln!("WARNING: cheatpath '{}' does not exist, skipping", raw_path);
                continue;
            }
            out.push(LoadedCheatPath { name: cp.name.clone(), path: p, tags: cp.tags.clone().unwrap_or_default(), readonly: cp.readonly.unwrap_or(false) });
        }
    }
    if let Ok(cwd) = std::env::current_dir() {
        let mut cur = Some(cwd.as_path());
        while let Some(dir) = cur {
            let cheat_dir = dir.join(".cheat");
            if cheat_dir.is_dir() {
                out.push(LoadedCheatPath { name: "cwd".to_string(), path: cheat_dir, tags: vec![], readonly: false });
                break;
            }
            cur = dir.parent();
        }
    }
    if out.is_empty() {
        return Err("config error: no cheatpaths specified".to_string());
    }
    Ok(out)
}

fn parse_frontmatter(content: &str) -> (Vec<String>, Option<String>, String) {
    if content.starts_with("---\n") || content.starts_with("---\r\n") {
        let content_lines: Vec<&str> = content.lines().collect();
        let mut end_idx = None;
        for (i, line) in content_lines.iter().enumerate().skip(1) {
            if line.trim() == "---" { end_idx = Some(i); break; }
        }
        if let Some(idx) = end_idx {
            let fm_content = content_lines[1..idx].join("\n");
            let mut tags = Vec::new();
            let mut syntax = None;
            if let Ok(val) = serde_yaml::from_str::<serde_yaml::Value>(&fm_content) {
                if let Some(m) = val.as_mapping() {
                    if let Some(t) = m.get(&serde_yaml::Value::String("tags".to_string())) {
                        if let Some(seq) = t.as_sequence() {
                            for item in seq {
                                if let Some(s) = item.as_str() { tags.push(s.to_string()); }
                            }
                        } else if let Some(s) = t.as_str() { tags.push(s.to_string()); }
                    }
                    if let Some(s) = m.get(&serde_yaml::Value::String("syntax".to_string())) {
                        if let Some(s_str) = s.as_str() { syntax = Some(s_str.to_string()); }
                    }
                }
            }
            let body = content_lines[idx+1..].join("\n");
            let body_with_newline = if body.is_empty() { body } else if content.ends_with('\n') && !body.ends_with('\n') { body + "\n" } else { body };
            return (tags, syntax, body_with_newline);
        }
    }
    (Vec::new(), None, content.to_string())
}

fn parse_sheet_file(path: &Path, cheatpath: &LoadedCheatPath) -> Option<Sheet> {
    let content = fs::read_to_string(path).ok()?;
    let rel = path.strip_prefix(&cheatpath.path).ok()?;
    let title = rel.to_string_lossy().replace("\\", "/");
    let (tags, syntax, body) = parse_frontmatter(&content);
    let mut all_tags = cheatpath.tags.clone();
    all_tags.extend(tags);
    Some(Sheet { title, file: path.to_path_buf(), cheatpath_name: cheatpath.name.clone(), cheatpath_path: cheatpath.path.clone(), tags: all_tags, syntax, body, raw_content: content })
}

fn collect_sheets(cheatpaths: &[LoadedCheatPath]) -> Vec<Sheet> {
    let mut sheets = Vec::new();
    for cp in cheatpaths {
        for entry in walkdir::WalkDir::new(&cp.path).follow_links(false).into_iter().filter_map(|e| e.ok()) {
            if entry.file_type().is_file() {
                if let Some(sheet) = parse_sheet_file(entry.path(), cp) {
                    sheets.push(sheet);
                }
            }
        }
    }
    sheets.sort_by(|a,b| a.title.cmp(&b.title));
    sheets
}

fn filter_sheets_by_path_name(sheets: &[Sheet], path_filter: Option<&str>, cheatpaths: &[LoadedCheatPath]) -> Result<Vec<Sheet>, String> {
    if let Some(pname) = path_filter {
        if !cheatpaths.iter().any(|cp| cp.name == pname) {
            return Err(format!("invalid option --path: cheatpath does not exist: {}", pname));
        }
        Ok(sheets.iter().filter(|s| s.cheatpath_name == pname).cloned().collect())
    } else {
        Ok(sheets.to_vec())
    }
}

fn filter_sheets_by_tag(sheets: &[Sheet], tag_filter: Option<&str>) -> Vec<Sheet> {
    if let Some(tag) = tag_filter {
        sheets.iter().filter(|s| s.tags.iter().any(|t| t == tag)).cloned().collect()
    } else {
        sheets.to_vec()
    }
}

fn filter_sheets_by_title_substring(sheets: &[Sheet], substr: Option<&str>) -> Vec<Sheet> {
    if let Some(q) = substr {
        let q_low = q.to_lowercase();
        sheets.iter().filter(|s| s.title.to_lowercase().contains(&q_low)).cloned().collect()
    } else {
        sheets.to_vec()
    }
}

fn find_sheet_by_title(sheets: &[Sheet], title: &str, cheatpaths: &[LoadedCheatPath], all: bool) -> Vec<Sheet> {
    let matches: Vec<Sheet> = sheets.iter().filter(|s| s.title == title).cloned().collect();
    if matches.is_empty() { return vec![]; }
    if all {
        // Order by cheatpath order? For -a view, we saw order personal then work (cheatpath order)
        let mut ordered = Vec::new();
        for cp in cheatpaths {
            for m in &matches {
                if m.cheatpath_name == cp.name {
                    ordered.push(m.clone());
                }
            }
        }
        // Also include any matches not in cheatpaths order (cwd etc)
        for m in matches {
            if !ordered.iter().any(|o| o.file == m.file) {
                ordered.push(m);
            }
        }
        return ordered;
    } else {
        // Most local (last in cheatpaths)
        let mut best: Option<Sheet> = None;
        let mut best_idx = 0;
        let mut found = false;
        for m in matches {
            if let Some(idx) = cheatpaths.iter().position(|cp| cp.name == m.cheatpath_name) {
                if !found || idx >= best_idx {
                    best = Some(m.clone());
                    best_idx = idx;
                    found = true;
                }
            } else {
                if !found {
                    best = Some(m.clone());
                    found = true;
                }
            }
        }
        if let Some(b) = best { vec![b] } else { vec![] }
    }
}

fn colorize_content(content: &str, syntax: Option<&str>, style: &str, formatter: &str, colorize_flag: bool, config_colorize: bool) -> String {
    let should_color = colorize_flag || config_colorize;
    if !should_color { return content.to_string(); }
    if style != "monokai" || formatter != "terminal256" {
        // For other formatters, fallback to simple (original for terminal gave bold etc)
        // We'll just return content for now
        return content.to_string();
    }
    let syntax_str = syntax.unwrap_or("text");
    let mut cmd = Command::new("python3");
    cmd.arg("-c").arg(format!(r#"
import sys
try:
    from pygments import highlight
    from pygments.lexers import get_lexer_by_name, TextLexer
    from pygments.formatters import Terminal256Formatter
    code = sys.stdin.read()
    syntax = "{}"
    try:
        lexer = get_lexer_by_name(syntax, stripall=False)
    except:
        lexer = TextLexer()
    fmt = Terminal256Formatter(style="{}")
    out = highlight(code, lexer, fmt)
    sys.stdout.write(out)
except Exception as e:
    sys.stdout.write(sys.stdin.read())
"#, syntax_str, style)).stdin(Stdio::piped()).stdout(Stdio::piped());
    if let Ok(mut child) = cmd.spawn() {
        if let Some(mut stdin) = child.stdin.take() {
            use std::io::Write;
            let _ = stdin.write_all(content.as_bytes());
        }
        if let Ok(output) = child.wait_with_output() {
            if output.status.success() {
                let mut out = String::from_utf8_lossy(&output.stdout).to_string();
                out = out.replace("\x1b[38;5;204m", "\x1b[38;5;197m");
                out = out.replace("\x1b[38;5;255m", "\x1b[38;5;231m");
                out = out.replace("\x1b[38;5;245m", "\x1b[38;5;242m");
                out = out.replace("\x1b[39m", "\x1b[0m");
                // Pygments adds extra reset? Cheat's output for "plain text" is "\x1b[38;5;231mplain text\x1b[0m\n" vs pyg "\x1b[38;5;231mplain text\x1b[0m\n" after replace should match
                return out;
            }
        }
    }
    format!("\x1b[38;5;231m{}\x1b[0m", content)
}

