fn handle_complete(args: &[String]) {
    let config_result = load_config();
    let cheatpaths = config_result.as_ref().ok().and_then(|(cfg,_)| load_cheatpaths(cfg).ok()).unwrap_or_default();
    let sheets = collect_sheets(&cheatpaths);
    let mut out_lines: Vec<String> = Vec::new();
    let directive = 4;
    if args.is_empty() || (args.len()==1 && args[0].is_empty()) {
        for s in sheets { out_lines.push(s.title); }
    } else if args.last().map(|s| s.starts_with("-")).unwrap_or(false) {
        let last = args.last().unwrap();
        let flags = vec!["--all","-a","--brief","-b","--colorize","-c","--completion","--conf","--directories","-d","--edit","-e","--help","-h","--init","--list","-l","--path","-p","--regex","-r","--rm","--search","-s","--tag","-t","--tags","-T","--update","-u","--version","-v"];
        for f in flags { if f.starts_with(last.as_str()) { out_lines.push(format!("{}\tflag", f)); } }
        // Also check for --completion shell names
        if "--completion".starts_with(last.as_str()) { out_lines.push("--completion\tGenerate shell completion script (`shell`: bash, zsh, fish, powershell)".to_string()); }
    } else if args.len() >=2 && args[args.len()-2] == "-p" {
        for cp in cheatpaths { out_lines.push(cp.name); }
    } else if args.len() >=2 && args[args.len()-2] == "-t" {
        let mut tags = BTreeSet::new();
        for s in sheets { for t in s.tags { tags.insert(t); } }
        for tag in tags { out_lines.push(tag); }
    } else if args.len() >=1 && args[0] == "-p" {
        // completion for -p ?
        for cp in cheatpaths { out_lines.push(cp.name); }
    } else {
        for s in sheets { out_lines.push(s.title); }
    }
    for line in out_lines { println!("{}", line); }
    println!(":{}", directive);
    eprintln!("Completion ended with directive: ShellCompDirectiveNoFileComp");
}

fn handle_completion(shell: &str) -> Result<(), String> {
    let mut cmd = build_cli();
    let shell_enum: Shell = match shell {
        "bash" => Shell::Bash,
        "zsh" => Shell::Zsh,
        "fish" => Shell::Fish,
        "powershell" => Shell::PowerShell,
        _ => return Err(format!("unsupported shell: {} (valid: bash, zsh, fish, powershell)", shell)),
    };
    let mut buf = Vec::new();
    clap_complete::generate(shell_enum, &mut cmd, "cheat", &mut buf);
    let output = String::from_utf8(buf).unwrap();
    print!("{}", output);
    Ok(())
}

fn find_writable_cheatpath<'a>(cheatpaths: &'a [LoadedCheatPath], path_filter: Option<&str>) -> Option<&'a LoadedCheatPath> {
    if let Some(pname) = path_filter {
        if let Some(cp) = cheatpaths.iter().find(|c| c.name == pname) {
            if !cp.readonly { return Some(cp); } else { return None; }
        } else { return None; }
    }
    for cp in cheatpaths.iter().rev() {
        if !cp.readonly { return Some(cp); }
    }
    None
}

fn handle_edit(config: &Config, cheatpaths: &[LoadedCheatPath], sheets: &[Sheet], sheet_name: &str, path_filter: Option<&str>) {
    let mut candidates = sheets.iter().filter(|s| s.title == sheet_name).cloned().collect::<Vec<_>>();
    if let Some(pname) = path_filter {
        candidates.retain(|s| s.cheatpath_name == pname);
    }
    let target_path: PathBuf;
    let is_existing = !candidates.is_empty();
    if is_existing {
        let sheet = {
            let mut best: Option<&Sheet> = None;
            let mut best_idx = 0;
            for cand in &candidates {
                if let Some(idx) = cheatpaths.iter().position(|cp| cp.name == cand.cheatpath_name) {
                    if best.is_none() || idx >= best_idx { best = Some(cand); best_idx = idx; }
                }
            }
            best.unwrap().clone()
        };
        let cp = cheatpaths.iter().find(|c| c.name == sheet.cheatpath_name).unwrap();
        if cp.readonly {
            let writable = find_writable_cheatpath(cheatpaths, path_filter);
            match writable {
                Some(w) => {
                    let dest = w.path.join(&sheet.title);
                    if let Some(parent) = dest.parent() { let _ = fs::create_dir_all(parent); }
                    if let Err(e) = fs::copy(&sheet.file, &dest) { eprintln!("failed to copy cheatsheet: {}", e); std::process::exit(1); }
                    target_path = dest;
                }
                None => { eprintln!("failed to get writeable path: no writeable cheatpaths found"); std::process::exit(1); }
            }
        } else {
            target_path = sheet.file.clone();
        }
    } else {
        let writable = find_writable_cheatpath(cheatpaths, path_filter);
        match writable {
            Some(w) => {
                let dest = w.path.join(sheet_name);
                if let Some(parent) = dest.parent() { let _ = fs::create_dir_all(parent); }
                target_path = dest;
            }
            None => { eprintln!("failed to get writeable path: no writeable cheatpaths found"); std::process::exit(1); }
        }
    }
    let editor = std::env::var("VISUAL").or(std::env::var("EDITOR")).unwrap_or_else(|_| config.editor.clone().unwrap_or_else(|| "vi".to_string()));
    let editor = if editor == "EDITOR_PATH" { std::env::var("VISUAL").or(std::env::var("EDITOR")).unwrap_or_else(|_| "vi".to_string()) } else { editor };
    let mut parts = editor.split_whitespace();
    let prog = parts.next().unwrap_or("vi");
    let args: Vec<String> = parts.map(|s| s.to_string()).collect();
    let mut cmd = Command::new(prog);
    for a in args { cmd.arg(a); }
    cmd.arg(&target_path);
    cmd.stdin(Stdio::inherit());
    cmd.stdout(Stdio::inherit());
    cmd.stderr(Stdio::inherit());
    let status = cmd.status();
    match status {
        Ok(s) if s.success() => std::process::exit(0),
        Ok(s) => { eprintln!("failed to edit cheatsheet: exit status {}", s.code().unwrap_or(1)); std::process::exit(1); }
        Err(e) => { eprintln!("failed to edit cheatsheet: {}", e); std::process::exit(1); }
    }
}

fn handle_rm(cheatpaths: &[LoadedCheatPath], sheets: &[Sheet], sheet_name: &str, path_filter: Option<&str>) {
    let mut candidates = sheets.iter().filter(|s| s.title == sheet_name).cloned().collect::<Vec<_>>();
    if let Some(pname) = path_filter {
        candidates.retain(|s| s.cheatpath_name == pname);
    }
    let target = {
        if candidates.is_empty() {
            eprintln!("No cheatsheet found for '{}'.", sheet_name);
            std::process::exit(2);
        }
        if candidates.len() == 1 {
            candidates[0].clone()
        } else {
            let mut best = &candidates[0];
            let mut best_idx = cheatpaths.iter().position(|cp| cp.name == best.cheatpath_name).unwrap_or(0);
            for cand in &candidates[1..] {
                if let Some(idx) = cheatpaths.iter().position(|cp| cp.name == cand.cheatpath_name) {
                    if idx > best_idx { best = cand; best_idx = idx; }
                }
            }
            best.clone()
        }
    };
    let cp = cheatpaths.iter().find(|c| c.name == target.cheatpath_name).unwrap();
    if cp.readonly {
        eprintln!("cheatsheet '{}' is read-only.", sheet_name);
        std::process::exit(1);
    }
    match fs::remove_file(&target.file) {
        Ok(_) => std::process::exit(0),
        Err(e) => { eprintln!("failed to remove cheatsheet: {}", e); std::process::exit(1); }
    }
}

