fn build_cli() -> ClapCommand {
    ClapCommand::new("cheat")
        .version(VERSION)
        .disable_version_flag(true)
        .disable_help_flag(true)
        .allow_external_subcommands(true)
        .arg(Arg::new("version").short('v').long("version").action(ArgAction::SetTrue).help("Print the version number"))
        .arg(Arg::new("help").short('h').long("help").action(ArgAction::SetTrue).help("help for cheat"))
        .arg(Arg::new("init").long("init").action(ArgAction::SetTrue).help("Write a default config file to stdout"))
        .arg(Arg::new("conf").long("conf").action(ArgAction::SetTrue).help("Display the config file path"))
        .arg(Arg::new("completion").long("completion").value_name("shell").help("Generate shell completion script (shell: bash, zsh, fish, powershell)"))
        .arg(Arg::new("update").short('u').long("update").action(ArgAction::SetTrue).help("Update git-backed cheatpaths"))
        .arg(Arg::new("directories").short('d').long("directories").action(ArgAction::SetTrue).help("List cheatsheet directories"))
        .arg(Arg::new("list").short('l').long("list").action(ArgAction::SetTrue).help("List cheatsheets"))
        .arg(Arg::new("brief").short('b').long("brief").action(ArgAction::SetTrue).help("List cheatsheets without file paths"))
        .arg(Arg::new("tags").short('T').long("tags").action(ArgAction::SetTrue).help("List all tags in use"))
        .arg(Arg::new("colorize").short('c').long("colorize").action(ArgAction::SetTrue).help("Colorize output"))
        .arg(Arg::new("all").short('a').long("all").action(ArgAction::SetTrue).help("Search among all cheatpaths"))
        .arg(Arg::new("regex").short('r').long("regex").action(ArgAction::SetTrue).help("Treat search <phrase> as a regex"))
        .arg(Arg::new("search").short('s').long("search").value_name("phrase").help("Search cheatsheets for phrase"))
        .arg(Arg::new("tag").short('t').long("tag").value_name("tag").help("Return only sheets matching tag"))
        .arg(Arg::new("path").short('p').long("path").value_name("name").help("Return only sheets found on cheatpath name"))
        .arg(Arg::new("edit").short('e').long("edit").value_name("cheatsheet").help("Edit cheatsheet"))
        .arg(Arg::new("rm").long("rm").value_name("cheatsheet").help("Remove (delete) cheatsheet"))
        .arg(Arg::new("cheatsheet").value_name("cheatsheet").required(false))
        .arg(Arg::new("extra").value_name("args").num_args(0..).hide(true))
}

fn config_path() -> PathBuf {
    if let Ok(p) = std::env::var("CHEAT_CONFIG_PATH") {
        return PathBuf::from(p);
    }
    if let Ok(xdg) = std::env::var("XDG_CONFIG_HOME") {
        let p = PathBuf::from(xdg).join("cheat").join("conf.yml");
        if p.exists() { return p; }
    }
    if let Ok(home) = std::env::var("HOME") {
        let p = PathBuf::from(&home).join(".config").join("cheat").join("conf.yml");
        if p.exists() { return p; }
        let p2 = PathBuf::from(&home).join(".cheat").join("conf.yml");
        if p2.exists() { return p2; }
    }
    let p = PathBuf::from("/etc/cheat/conf.yml");
    if p.exists() { return p; }
    if let Ok(p) = std::env::var("CHEAT_CONFIG_PATH") {
        return PathBuf::from(p);
    }
    if let Ok(xdg) = std::env::var("XDG_CONFIG_HOME") {
        return PathBuf::from(xdg).join("cheat").join("conf.yml");
    }
    if let Ok(home) = std::env::var("HOME") {
        return PathBuf::from(home).join(".config").join("cheat").join("conf.yml");
    }
    PathBuf::from("/etc/cheat/conf.yml")
}

fn default_config_path_for_init() -> PathBuf {
    config_path()
}

fn expand_path(p: &str) -> String {
    if p.starts_with("~/") {
        if let Ok(home) = std::env::var("HOME") {
            return format!("{}{}", home, &p[1..]);
        }
    } else if p == "~" {
        if let Ok(home) = std::env::var("HOME") { return home; }
    }
    p.to_string()
}

fn load_config() -> Result<(Config, PathBuf), String> {
    let mut search_paths = Vec::new();
    if let Ok(p) = std::env::var("CHEAT_CONFIG_PATH") {
        search_paths.push(PathBuf::from(p));
    } else {
        if let Ok(xdg) = std::env::var("XDG_CONFIG_HOME") {
            search_paths.push(PathBuf::from(xdg).join("cheat").join("conf.yml"));
        }
        if let Ok(home) = std::env::var("HOME") {
            search_paths.push(PathBuf::from(home).join(".config").join("cheat").join("conf.yml"));
            search_paths.push(PathBuf::from(home).join(".cheat").join("conf.yml"));
        }
        search_paths.push(PathBuf::from("/etc/cheat/conf.yml"));
    }
    let mut found_path: Option<PathBuf> = None;
    let mut config_content: Option<String> = None;
    for p in &search_paths {
        if p.exists() {
            match fs::read_to_string(p) {
                Ok(c) => {
                    found_path = Some(p.clone());
                    config_content = Some(c);
                    break;
                }
                Err(e) => return Err(format!("failed to read config: {}", e)),
            }
        }
    }
    if let (Some(path), Some(content)) = (found_path, config_content) {
        match serde_yaml::from_str::<Config>(&content) {
            Ok(cfg) => Ok((cfg, path)),
            Err(e) => Err(format!("failed to parse config: {}", e)),
        }
    } else {
        Err("NOT_FOUND".to_string())
    }
}

fn prompt_create_config(default_path: &Path) -> Result<(), String> {
    use std::io::{self, Write};
    eprint!("A config file was not found. Would you like to create one now? [Y/n]: ");
    let _ = io::stderr().flush();
    // Also need to print to stdout? Original printed to stdout.
    print!("A config file was not found. Would you like to create one now? [Y/n]: ");
    let _ = io::stdout().flush();
    // Actually we need to capture: original's prompt was on stdout, not stderr. Let's print to stdout.
    let mut line = String::new();
    if io::stdin().read_line(&mut line).map_err(|e| format!("failed to prompt: {}", e))? == 0 {
        return Err("failed to prompt: EOF".to_string());
    }
    let ans = line.trim().to_lowercase();
    if ans != "" && ans != "y" && ans != "yes" {
        return Ok(());
    }
    eprint!("Would you like to download the community cheatsheets? [Y/n]: ");
    let _ = io::stderr().flush();
    print!("Would you like to download the community cheatsheets? [Y/n]: ");
    let _ = io::stdout().flush();
    let mut line2 = String::new();
    if io::stdin().read_line(&mut line2).map_err(|e| format!("failed to prompt: {}", e))? == 0 {
        return Err("failed to prompt: EOF".to_string());
    }
    let init_content = generate_init_content();
    if let Some(parent) = default_path.parent() {
        fs::create_dir_all(parent).map_err(|e| format!("failed to create config dir: {}", e))?;
    }
    fs::write(&default_path, init_content).map_err(|e| format!("failed to write config: {}", e))?;
    let ans2 = line2.trim().to_lowercase();
    if ans2 == "" || ans2 == "y" || ans2 == "yes" {
        let community_path = if let Some(parent) = default_path.parent() {
            parent.join("cheatsheets").join("community")
        } else {
            PathBuf::from("/tmp/cheatsheets/community")
        };
        eprintln!("Cloning community cheatsheets to {}.", community_path.display());
        println!("Cloning community cheatsheets to {}.", community_path.display());
        let output = Command::new("git").arg("clone").arg("https://github.com/cheat/cheatsheets.git").arg(&community_path).output();
        match output {
            Ok(o) if o.status.success() => {},
            Ok(o) => {
                let err = String::from_utf8_lossy(&o.stderr);
                return Err(format!("failed to run installer: failed to clone cheatsheets: {}", err));
            }
            Err(e) => {
                return Err(format!("failed to run installer: failed to clone cheatsheets: {}", e));
            }
        }
        let _ = fs::create_dir_all(&community_path);
    }
    eprintln!("Created config file: {}", default_path.display());
    println!("Created config file: {}", default_path.display());
    eprintln!("Please read this file for advanced configuration information.");
    println!("Please read this file for advanced configuration information.");
    Ok(())
}

fn generate_init_content() -> String {
    let cfg_path = default_config_path_for_init();
    let base = cfg_path.parent().unwrap_or(Path::new("/tmp"));
    let personal = base.join("cheatsheets").join("personal");
    let work = base.join("cheatsheets").join("work");
    let community = base.join("cheatsheets").join("community");
    format!(r#"---
# The editor to use with 'cheat -e <sheet>'. Overridden by $VISUAL or $EDITOR.
editor: EDITOR_PATH

# Should 'cheat' always colorize output?
colorize: false

# Which 'chroma' colorscheme should be applied to the output?
# Options are available here:
#   https://github.com/alecthomas/chroma/tree/master/styles
style: monokai

# Which 'chroma' "formatter" should be applied?
# One of: "terminal", "terminal256", "terminal16m"
formatter: terminal256

# Through which pager should output be piped?
# 'less -FRX' is recommended on Unix systems
# 'more' is recommended on Windows
pager: cat

# The paths at which cheatsheets are available. Tags associated with a cheatpath
# are automatically attached to all cheatsheets residing on that path.
#
# Whenever cheatsheets share the same title (like 'tar'), the most local
# cheatsheets (those which come later in this file) take precedence over the
# less local sheets. This allows you to create your own "overides" for
# "upstream" cheatsheets.
#
# But what if you want to view the "upstream" cheatsheets instead of your own?
# Cheatsheets may be filtered by 'tags' in combination with the '--tag' flag.
# 
# Example: 'cheat tar --tag=community' will display the 'tar' cheatsheet that
# is tagged as 'community' rather than your own.
#
# Paths that come earlier are considered to be the most "global", and paths
# that come later are considered to be the most "local". The most "local" paths
# take precedence.
#
# See: https://github.com/cheat/cheat/blob/master/doc/cheat.1.md#cheatpaths
cheatpaths:

  # Cheatsheets that are tagged "personal" are stored here by default:
  - name: personal
    path: {}
    tags: [ personal ]
    readonly: false

  # Cheatsheets that are tagged "work" are stored here by default:
  - name: work
    path: {}
    tags: [ work ]
    readonly: false

  # Community cheatsheets (https://github.com/cheat/cheatsheets):
  # To install: git clone https://github.com/cheat/cheatsheets {}
  #- name: community
  #  path: {}
  #  tags: [ community ]
  #  readonly: true

  # You can also use glob patterns to automatically load cheatsheets from all
  # directories that match.
  #
  # Example: overload cheatsheets for projects under ~/src/github.com/example/*/
  #- name: example-projects
  #  path: ~/src/github.com/example/**/.cheat
  #  tags: [ example ]
  #  readonly: true
"#, personal.display(), work.display(), community.display(), community.display())
}

fn load_cheatpaths(config: &Config) -> Result<Vec<LoadedCheatPath>, String> {
    let mut out = Vec::new();
    for cp in &config.cheatpaths {
        let raw_path = expand_path(&cp.path);
        let has_glob = raw_path.contains('*') || raw_path.contains('?') || raw_path.contains('[');
        if has_glob {
            match glob::glob(&raw_path) {
                Ok(paths) => {
                    let mut matched = 0;
                    for entry in paths {
                        if let Ok(p) = entry {
                            if p.is_dir() {
                                out.push(LoadedCheatPath { name: cp.name.clone(), path: p, tags: cp.tags.clone().unwrap_or_default(), readonly: cp.readonly.unwrap_or(false) });
                                matched += 1;
                            }
                        }
                    }
                    if matched == 0 {
                        eprintln!("WARNING: cheatpath '{}' does not exist, skipping", raw_path);
                    }
                }
                Err(_) => {
                    eprintln!("WARNING: cheatpath '{}' does not exist, skipping", raw_path);
                }
            }
        } else {
            let p = PathBuf::from(&raw_path);
            if !p.exists() {
                eprintln!("WARNING: cheatpath '{}' does not exist, skipping", raw_path);
                continue;
            }
            out.push(LoadedCheatPath { name: cp.name.clone(), path: p, tags: cp.tags.clone().unwrap_or_default(), readonly: cp.readonly.unwrap_or(false) });
        }
    }
    if let Ok(cwd) = std::env::current_dir() {
        let mut cur = Some(cwd.as_path());
        while let Some(dir) = cur {
            let cheat_dir = dir.join(".cheat");
            if cheat_dir.is_dir() {
                out.push(LoadedCheatPath { name: "cwd".to_string(), path: cheat_dir, tags: vec![], readonly: false });
                break;
            }
            cur = dir.parent();
        }
    }
    if out.is_empty() {
        return Err("config error: no cheatpaths specified".to_string());
    }
    Ok(out)
}

fn parse_frontmatter(content: &str) -> (Vec<String>, Option<String>, String) {
    if content.starts_with("---\n") || content.starts_with("---\r\n") {
        let content_lines: Vec<&str> = content.lines().collect();
        let mut end_idx = None;
        for (i, line) in content_lines.iter().enumerate().skip(1) {
            if line.trim() == "---" { end_idx = Some(i); break; }
        }
        if let Some(idx) = end_idx {
            let fm_content = content_lines[1..idx].join("\n");
            let mut tags = Vec::new();
            let mut syntax = None;
            if let Ok(val) = serde_yaml::from_str::<serde_yaml::Value>(&fm_content) {
                if let Some(m) = val.as_mapping() {
                    if let Some(t) = m.get(&serde_yaml::Value::String("tags".to_string())) {
                        if let Some(seq) = t.as_sequence() {
                            for item in seq {
                                if let Some(s) = item.as_str() { tags.push(s.to_string()); }
                            }
                        } else if let Some(s) = t.as_str() { tags.push(s.to_string()); }
                    }
                    if let Some(s) = m.get(&serde_yaml::Value::String("syntax".to_string())) {
                        if let Some(s_str) = s.as_str() { syntax = Some(s_str.to_string()); }
                    }
                }
            }
            let body = content_lines[idx+1..].join("\n");
            let body_with_newline = if body.is_empty() { body } else if content.ends_with('\n') && !body.ends_with('\n') { body + "\n" } else { body };
            return (tags, syntax, body_with_newline);
        }
    }
    (Vec::new(), None, content.to_string())
}

fn parse_sheet_file(path: &Path, cheatpath: &LoadedCheatPath) -> Option<Sheet> {
    let content = fs::read_to_string(path).ok()?;
    let rel = path.strip_prefix(&cheatpath.path).ok()?;
    let title = rel.to_string_lossy().replace("\\", "/");
    let (tags, syntax, body) = parse_frontmatter(&content);
    let mut all_tags = cheatpath.tags.clone();
    all_tags.extend(tags);
    Some(Sheet { title, file: path.to_path_buf(), cheatpath_name: cheatpath.name.clone(), cheatpath_path: cheatpath.path.clone(), tags: all_tags, syntax, body, raw_content: content })
}

fn collect_sheets(cheatpaths: &[LoadedCheatPath]) -> Vec<Sheet> {
    let mut sheets = Vec::new();
    for cp in cheatpaths {
        for entry in walkdir::WalkDir::new(&cp.path).follow_links(false).into_iter().filter_map(|e| e.ok()) {
            if entry.file_type().is_file() {
                if let Some(sheet) = parse_sheet_file(entry.path(), cp) {
                    sheets.push(sheet);
                }
            }
        }
    }
    sheets.sort_by(|a,b| a.title.cmp(&b.title));
    sheets
}

fn filter_sheets_by_path_name(sheets: &[Sheet], path_filter: Option<&str>, cheatpaths: &[LoadedCheatPath]) -> Result<Vec<Sheet>, String> {
    if let Some(pname) = path_filter {
        if !cheatpaths.iter().any(|cp| cp.name == pname) {
            return Err(format!("invalid option --path: cheatpath does not exist: {}", pname));
        }
        Ok(sheets.iter().filter(|s| s.cheatpath_name == pname).cloned().collect())
    } else {
        Ok(sheets.to_vec())
    }
}

fn filter_sheets_by_tag(sheets: &[Sheet], tag_filter: Option<&str>) -> Vec<Sheet> {
    if let Some(tag) = tag_filter {
        sheets.iter().filter(|s| s.tags.iter().any(|t| t == tag)).cloned().collect()
    } else {
        sheets.to_vec()
    }
}

fn filter_sheets_by_title_substring(sheets: &[Sheet], substr: Option<&str>) -> Vec<Sheet> {
    if let Some(q) = substr {
        let q_low = q.to_lowercase();
        sheets.iter().filter(|s| s.title.to_lowercase().contains(&q_low)).cloned().collect()
    } else {
        sheets.to_vec()
    }
}

fn find_sheet_by_title(sheets: &[Sheet], title: &str, cheatpaths: &[LoadedCheatPath], all: bool) -> Vec<Sheet> {
    let matches: Vec<Sheet> = sheets.iter().filter(|s| s.title == title).cloned().collect();
    if matches.is_empty() { return vec![]; }
    if all {
        // Order by cheatpath order? For -a view, we saw order personal then work (cheatpath order)
        let mut ordered = Vec::new();
        for cp in cheatpaths {
            for m in &matches {
                if m.cheatpath_name == cp.name {
                    ordered.push(m.clone());
                }
            }
        }
        // Also include any matches not in cheatpaths order (cwd etc)
        for m in matches {
            if !ordered.iter().any(|o| o.file == m.file) {
                ordered.push(m);
            }
        }
        return ordered;
    } else {
        // Most local (last in cheatpaths)
        let mut best: Option<Sheet> = None;
        let mut best_idx = 0;
        let mut found = false;
        for m in matches {
            if let Some(idx) = cheatpaths.iter().position(|cp| cp.name == m.cheatpath_name) {
                if !found || idx >= best_idx {
                    best = Some(m.clone());
                    best_idx = idx;
                    found = true;
                }
            } else {
                if !found {
                    best = Some(m.clone());
                    found = true;
                }
            }
        }
        if let Some(b) = best { vec![b] } else { vec![] }
    }
}

fn colorize_content(content: &str, syntax: Option<&str>, style: &str, formatter: &str, colorize_flag: bool, config_colorize: bool) -> String {
    let should_color = colorize_flag || config_colorize;
    if !should_color { return content.to_string(); }
    if style != "monokai" || formatter != "terminal256" {
        // For other formatters, fallback to simple (original for terminal gave bold etc)
        // We'll just return content for now
        return content.to_string();
    }
    let syntax_str = syntax.unwrap_or("text");
    let mut cmd = Command::new("python3");
    cmd.arg("-c").arg(format!(r#"
import sys
try:
    from pygments import highlight
    from pygments.lexers import get_lexer_by_name, TextLexer
    from pygments.formatters import Terminal256Formatter
    code = sys.stdin.read()
    syntax = "{}"
    try:
        lexer = get_lexer_by_name(syntax, stripall=False)
    except:
        lexer = TextLexer()
    fmt = Terminal256Formatter(style="{}")
    out = highlight(code, lexer, fmt)
    sys.stdout.write(out)
except Exception as e:
    sys.stdout.write(sys.stdin.read())
"#, syntax_str, style)).stdin(Stdio::piped()).stdout(Stdio::piped());
    if let Ok(mut child) = cmd.spawn() {
        if let Some(mut stdin) = child.stdin.take() {
            use std::io::Write;
            let _ = stdin.write_all(content.as_bytes());
        }
        if let Ok(output) = child.wait_with_output() {
            if output.status.success() {
                let mut out = String::from_utf8_lossy(&output.stdout).to_string();
                out = out.replace("\x1b[38;5;204m", "\x1b[38;5;197m");
                out = out.replace("\x1b[38;5;255m", "\x1b[38;5;231m");
                out = out.replace("\x1b[38;5;245m", "\x1b[38;5;242m");
                out = out.replace("\x1b[39m", "\x1b[0m");
                // Pygments adds extra reset? Cheat's output for "plain text" is "\x1b[38;5;231mplain text\x1b[0m\n" vs pyg "\x1b[38;5;231mplain text\x1b[0m\n" after replace should match
                return out;
            }
        }
    }
    format!("\x1b[38;5;231m{}\x1b[0m", content)
}

fn print_help_and_exit() {
    let help = r#"cheat allows you to create and view interactive cheatsheets on the
command-line. It was designed to help remind *nix system administrators of
options for commands that they use frequently, but not frequently enough to
remember.

Usage:
  cheat [cheatsheet] [flags]

Examples:
  To initialize a config file:
    mkdir -p ~/.config/cheat && cheat --init > ~/.config/cheat/conf.yml

  To view the tar cheatsheet:
