}

fn handle_complete(args: &[String]) {
    let config_result = load_config();
    let cheatpaths = config_result.as_ref().ok().and_then(|(cfg,_)| load_cheatpaths(cfg).ok()).unwrap_or_default();
    let sheets = collect_sheets(&cheatpaths);
    let mut out_lines: Vec<String> = Vec::new();
    let directive = 4;
    if args.is_empty() || (args.len()==1 && args[0].is_empty()) {
        for s in sheets { out_lines.push(s.title); }
    } else if args.last().map(|s| s.starts_with("-")).unwrap_or(false) {
        let last = args.last().unwrap();
        let flags = vec!["--all","-a","--brief","-b","--colorize","-c","--completion","--conf","--directories","-d","--edit","-e","--help","-h","--init","--list","-l","--path","-p","--regex","-r","--rm","--search","-s","--tag","-t","--tags","-T","--update","-u","--version","-v"];
        for f in flags { if f.starts_with(last.as_str()) { out_lines.push(format!("{}\tflag", f)); } }
        // Also check for --completion shell names
        if "--completion".starts_with(last.as_str()) { out_lines.push("--completion\tGenerate shell completion script (`shell`: bash, zsh, fish, powershell)".to_string()); }
    } else if args.len() >=2 && args[args.len()-2] == "-p" {
        for cp in cheatpaths { out_lines.push(cp.name); }
    } else if args.len() >=2 && args[args.len()-2] == "-t" {
        let mut tags = BTreeSet::new();
        for s in sheets { for t in s.tags { tags.insert(t); } }
        for tag in tags { out_lines.push(tag); }
    } else if args.len() >=1 && args[0] == "-p" {
        // completion for -p ?
        for cp in cheatpaths { out_lines.push(cp.name); }
    } else {
        for s in sheets { out_lines.push(s.title); }
    }
    for line in out_lines { println!("{}", line); }
    println!(":{}", directive);
    eprintln!("Completion ended with directive: ShellCompDirectiveNoFileComp");
}

fn handle_completion(shell: &str) -> Result<(), String> {
    let mut cmd = build_cli();
    let shell_enum: Shell = match shell {
        "bash" => Shell::Bash,
        "zsh" => Shell::Zsh,
        "fish" => Shell::Fish,
        "powershell" => Shell::PowerShell,
        _ => return Err(format!("unsupported shell: {} (valid: bash, zsh, fish, powershell)", shell)),
    };
    let mut buf = Vec::new();
    clap_complete::generate(shell_enum, &mut cmd, "cheat", &mut buf);
    let output = String::from_utf8(buf).unwrap();
    print!("{}", output);
    Ok(())
}

fn find_writable_cheatpath<'a>(cheatpaths: &'a [LoadedCheatPath], path_filter: Option<&str>) -> Option<&'a LoadedCheatPath> {
    if let Some(pname) = path_filter {
        if let Some(cp) = cheatpaths.iter().find(|c| c.name == pname) {
            if !cp.readonly { return Some(cp); } else { return None; }
        } else { return None; }
    }
    for cp in cheatpaths.iter().rev() {
        if !cp.readonly { return Some(cp); }
    }
    None
}

fn handle_edit(config: &Config, cheatpaths: &[LoadedCheatPath], sheets: &[Sheet], sheet_name: &str, path_filter: Option<&str>) {
    let mut candidates = sheets.iter().filter(|s| s.title == sheet_name).cloned().collect::<Vec<_>>();
    if let Some(pname) = path_filter {
        candidates.retain(|s| s.cheatpath_name == pname);
    }
    let target_path: PathBuf;
    let is_existing = !candidates.is_empty();
    if is_existing {
        let sheet = {
            let mut best: Option<&Sheet> = None;
            let mut best_idx = 0;
            for cand in &candidates {
                if let Some(idx) = cheatpaths.iter().position(|cp| cp.name == cand.cheatpath_name) {
                    if best.is_none() || idx >= best_idx { best = Some(cand); best_idx = idx; }
                }
            }
            best.unwrap().clone()
        };
        let cp = cheatpaths.iter().find(|c| c.name == sheet.cheatpath_name).unwrap();
        if cp.readonly {
            let writable = find_writable_cheatpath(cheatpaths, path_filter);
            match writable {
                Some(w) => {
                    let dest = w.path.join(&sheet.title);
                    if let Some(parent) = dest.parent() { let _ = fs::create_dir_all(parent); }
                    if let Err(e) = fs::copy(&sheet.file, &dest) { eprintln!("failed to copy cheatsheet: {}", e); std::process::exit(1); }
                    target_path = dest;
                }
                None => { eprintln!("failed to get writeable path: no writeable cheatpaths found"); std::process::exit(1); }
            }
        } else {
            target_path = sheet.file.clone();
        }
    } else {
        let writable = find_writable_cheatpath(cheatpaths, path_filter);
        match writable {
            Some(w) => {
                let dest = w.path.join(sheet_name);
                if let Some(parent) = dest.parent() { let _ = fs::create_dir_all(parent); }
                target_path = dest;
            }
            None => { eprintln!("failed to get writeable path: no writeable cheatpaths found"); std::process::exit(1); }
        }
    }
    let editor = std::env::var("VISUAL").or(std::env::var("EDITOR")).unwrap_or_else(|_| config.editor.clone().unwrap_or_else(|| "vi".to_string()));
    let editor = if editor == "EDITOR_PATH" { std::env::var("VISUAL").or(std::env::var("EDITOR")).unwrap_or_else(|_| "vi".to_string()) } else { editor };
    let mut parts = editor.split_whitespace();
    let prog = parts.next().unwrap_or("vi");
    let args: Vec<String> = parts.map(|s| s.to_string()).collect();
    let mut cmd = Command::new(prog);
    for a in args { cmd.arg(a); }
    cmd.arg(&target_path);
    cmd.stdin(Stdio::inherit());
    cmd.stdout(Stdio::inherit());
    cmd.stderr(Stdio::inherit());
    let status = cmd.status();
    match status {
        Ok(s) if s.success() => std::process::exit(0),
        Ok(s) => { eprintln!("failed to edit cheatsheet: exit status {}", s.code().unwrap_or(1)); std::process::exit(1); }
        Err(e) => { eprintln!("failed to edit cheatsheet: {}", e); std::process::exit(1); }
    }
}

fn handle_rm(cheatpaths: &[LoadedCheatPath], sheets: &[Sheet], sheet_name: &str, path_filter: Option<&str>) {
    let mut candidates = sheets.iter().filter(|s| s.title == sheet_name).cloned().collect::<Vec<_>>();
    if let Some(pname) = path_filter {
        candidates.retain(|s| s.cheatpath_name == pname);
    }
    let target = {
        if candidates.is_empty() {
            eprintln!("No cheatsheet found for '{}'.", sheet_name);
            std::process::exit(2);
        }
        if candidates.len() == 1 {
            candidates[0].clone()
        } else {
            let mut best = &candidates[0];
            let mut best_idx = cheatpaths.iter().position(|cp| cp.name == best.cheatpath_name).unwrap_or(0);
            for cand in &candidates[1..] {
                if let Some(idx) = cheatpaths.iter().position(|cp| cp.name == cand.cheatpath_name) {
                    if idx > best_idx { best = cand; best_idx = idx; }
                }
            }
            best.clone()
        }
    };
    let cp = cheatpaths.iter().find(|c| c.name == target.cheatpath_name).unwrap();
    if cp.readonly {
        eprintln!("cheatsheet '{}' is read-only.", sheet_name);
        std::process::exit(1);
    }
    match fs::remove_file(&target.file) {
        Ok(_) => std::process::exit(0),
        Err(e) => { eprintln!("failed to remove cheatsheet: {}", e); std::process::exit(1); }
    }
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    if args.len() > 1 && args[1] == "__complete" {
        handle_complete(&args[2..]);
        return;
    }
    let matches = build_cli().try_get_matches();
    let m = match matches {
        Ok(m) => m,
        Err(e) => {
            // clap error handling: print error and exit
            let _ = e.print();
            std::process::exit(e.exit_code());
        }
    };
    if m.get_flag("version") {
        println!("{}", VERSION);
        std::process::exit(0);
    }
    if m.get_flag("help") {
        print_help_and_exit();
    }
    if m.get_flag("init") {
        let content = generate_init_content();
        print!("{}", content);
        return;
    }
    if m.contains_id("completion") {
        if let Some(shell) = m.get_one::<String>("completion") {
            if let Err(e) = handle_completion(shell) {
                eprintln!("{}", e);
                std::process::exit(1);
            }
            return;
        } else {
            // flag needs argument
            eprintln!("flag needs an argument: --completion");
            std::process::exit(1);
        }
    }
    // Handle missing argument cases for required options
    // clap will handle missing args automatically, but we need to ensure --rm, -e, -p, -s etc produce correct errors
    // For manual check: if edit or rm missing value, clap already errors.

    if m.get_flag("conf") {
        match load_config() {
            Ok((_, path)) => { println!("{}", path.display()); }
            Err(e) if e == "NOT_FOUND" => {
                let default_path = default_config_path_for_init();
                // For --conf, original prompt is same but we need to handle Y/n
                // Duplicate prompt logic but simpler: call prompt_create_config
                // However prompt_create_config currently prints to both stdout and stderr; for --conf we should ensure prompt printed to stdout as original did
                // Use same function
                match prompt_create_config(&default_path) {
                    Ok(()) => {
                        if default_path.exists() {
                            println!("{}", default_path.display());
                        } else {
                            // User said n, just exit 0 (prompt already printed)
                        }
                    }
                    Err(msg) => {
                        if msg.contains("failed to prompt: EOF") {
                            eprintln!("failed to create config: {}", msg);
                            // Also need to print prompt to stdout? Already printed in prompt_create_config
                            std::process::exit(1);
                        } else {
                            eprintln!("{}", msg);
                            std::process::exit(1);
                        }
                    }
                }
            }
            Err(e) => { eprintln!("failed to load config: {}", e); std::process::exit(1); }
        }
        return;
    }
    // update
    if m.get_flag("update") {
        // Need config
        let (config, _) = match load_config() {
            Ok(v) => v,
            Err(e) if e == "NOT_FOUND" => {
                let default_path = default_config_path_for_init();
                match prompt_create_config(&default_path) {
                    Ok(()) => std::process::exit(0),
                    Err(msg) => { eprintln!("A config file was not found. Would you like to create one now? [Y/n]: failed to create config: {}", msg); std::process::exit(1); }
                }
            }
            Err(e) => { eprintln!("failed to load config: {}", e); std::process::exit(1); }
        };
        let cheatpaths = match load_cheatpaths(&config) {
            Ok(cp) => cp,
            Err(e) => { eprintln!("{}", e); std::process::exit(1); }
        };
        let path_filter = m.get_one::<String>("path").map(|s| s.as_str());
        if let Some(pname) = path_filter {
            if !cheatpaths.iter().any(|c| &c.name == pname) {
                eprintln!("invalid option --path: cheatpath does not exist: {}", pname);
                std::process::exit(1);
            }
        }
        let mut exit_code = 0;
        let mut paths_to_update: Vec<&LoadedCheatPath> = Vec::new();
        if let Some(pname) = path_filter {
            if let Some(cp) = cheatpaths.iter().find(|c| &c.name == pname) { paths_to_update.push(cp); }
        } else {
            for cp in &cheatpaths { paths_to_update.push(cp); }
        }
        for cp in paths_to_update {
            let git_dir = cp.path.join(".git");
            if !git_dir.exists() {
                println!("{}: skipped (not a git repository)", cp.name);
                continue;
            }
            let remote_check = Command::new("git").arg("-C").arg(&cp.path).arg("remote").output();
            let has_remote = match remote_check {
                Ok(out) => {
                    let s = String::from_utf8_lossy(&out.stdout).trim().to_string();
                    !s.is_empty() && out.status.success()
                }
                Err(_) => false,
            };
            if !has_remote {
                eprintln!("{}: error (remote not found)", cp.name);
                exit_code = 1;
                continue;
            }
            let pull = Command::new("git").arg("-C").arg(&cp.path).arg("pull").output();
            match pull {
                Ok(o) if o.status.success() => println!("{}: updated", cp.name),
                Ok(o) => { let err = String::from_utf8_lossy(&o.stderr); eprintln!("{}: error ({})", cp.name, err.trim()); exit_code = 1; }
                Err(e) => { eprintln!("{}: error ({})", cp.name, e); exit_code = 1; }
            }
        }
        std::process::exit(exit_code);
    }

    // For other commands, need config
    let (config, _) = match load_config() {
        Ok(v) => v,
        Err(e) if e == "NOT_FOUND" => {
            let default_path = default_config_path_for_init();
            match prompt_create_config(&default_path) {
                Ok(()) => std::process::exit(0),
                Err(msg) => {
                    // Need to distinguish: for missing config with EOF, original printed "A config file was not found. Would you like to create one now? [Y/n]: failed to create config: failed to prompt: EOF"
                    // Our prompt_create_config already printed the first prompt to stdout, but we need to also print the prefix for the error?
                    // Let's just print as original.
                    if msg.contains("failed to prompt") {
                        // The prompt was already printed to stdout via prompt_create_config, now print error to stderr
                        eprintln!("failed to create config: {}", msg);
                        // Also the stdout already has prompt, but we need to ensure stdout contains prompt line.
                        // Our prompt_create_config printed prompt to both stdout and stderr (we did both). Original printed to stdout only.
                        // We'll keep as is.
                    } else {
                        eprintln!("{}", msg);
                    }
                    std::process::exit(1);
                }
            }
        }
        Err(e) => { eprintln!("failed to load config: {}", e); std::process::exit(1); }
    };
    let cheatpaths = match load_cheatpaths(&config) {
        Ok(cp) => cp,
        Err(e) => { eprintln!("{}", e); std::process::exit(1); }
    };
    // Validate path filter early
    let path_filter = m.get_one::<String>("path").map(|s| s.as_str());
    if let Some(pname) = path_filter {
        if !cheatpaths.iter().any(|c| &c.name == pname) {
            eprintln!("invalid option --path: cheatpath does not exist: {}", pname);
            std::process::exit(1);
        }
    }
    // Handle flag needs argument errors manually for --rm and -e etc? Clap will handle missing values, but we need to ensure error messages match original: "flag needs an argument: --rm" and "flag needs an argument: 'e' in -e"
    // Clap's error messages will be similar but may differ slightly. We'll rely on clap's default.

    let all_sheets = collect_sheets(&cheatpaths);

    // Directories
    if m.get_flag("directories") {
        let max_name_len = cheatpaths.iter().map(|c| c.name.len()).max().unwrap_or(0);
        for cp in &cheatpaths {
            let spaces = " ".repeat(max_name_len - cp.name.len() + 1);
            println!("{}:{}{}", cp.name, spaces, cp.path.display());
        }
        return;
    }
    // Edit
    if m.contains_id("edit") {
        if let Some(sheet_name) = m.get_one::<String>("edit") {
            handle_edit(&config, &cheatpaths, &all_sheets, sheet_name, path_filter);
            return;
        } else {
            // Should be handled by clap as error: flag needs argument
            eprintln!("flag needs an argument: 'e' in -e");
            std::process::exit(1);
        }
    }
    if m.contains_id("rm") {
        if let Some(sheet_name) = m.get_one::<String>("rm") {
