            // Single sheet, just print body (no header)
            let sheet = &matches[0];
            let body = &sheet.body;
            let output = colorize_content(body, sheet.syntax.as_deref(), &style, &formatter, is_colorize_flag, config_colorize);
            // Need to pipe through pager? Original uses pager cat. We'll just print to stdout.
