            if pager != "cat" && !pager.is_empty() {
                let mut child = Command::new("sh").arg("-c").arg(&pager).stdin(Stdio::piped()).spawn().unwrap_or_else(|_| { println!("{}", output); std::process::exit(0); });
                if let Some(mut stdin) = child.stdin.take() {
